function taskCard(t,p,showProject=false){const overdue=!t.done&&t.date&&t.date<today();return `<article class="task-card ${t.done?'done':''}"><input class="task-check" type="checkbox" data-action="toggle-task" data-project="${p.id}" data-task="${t.id}" ${t.done?'checked':''} aria-label="Marquer ${esc(t.title)} comme terminée"><div class="task-main"><h3>${esc(t.title)}</h3>${t.description?`<p>${esc(t.description)}</p>`:''}${t.address?`<p class="task-address">📍 <a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(t.address)}" target="_blank" rel="noopener">${esc(t.address)}</a></p>`:''}<div class="task-meta">${t.date?`<span class="pill ${overdue?'late':''}">📅 ${fmt(t.date,{day:'numeric',month:'short'})}</span>`:''}${t.time?`<span class="pill time">◷ ${esc(t.time)}</span>`:''}${showProject?`<span class="pill">${esc(p.emoji||'🌷')} ${esc(p.title)}</span>`:''}${t.done?'<span class="pill done">Terminé</span>':overdue?'<span class="pill late">En retard</span>':''}</div></div><div class="task-actions"><button class="icon-btn" data-action="edit-project" data-id="${p.id}" title="Modifier le projet" aria-label="Modifier le projet">✎</button><button class="icon-btn" data-action="ics" data-project="${p.id}" data-task="${t.id}" title="Ajouter au calendrier" aria-label="Ajouter au calendrier">↗</button></div></article>`}
function projectCard(p,history=false){return `<a class="project-card ${history?'history-card':''}" href="planning.html?id=${encodeURIComponent(p.id)}"><span class="project-emoji" style="background:${p.color||'var(--rose-light)'}">${esc(p.emoji||'🌷')}</span><div class="project-info"><h3>${esc(p.title)}</h3><p>${taskCount(p)} tâche${taskCount(p)>1?'s':''} · ${doneCount(p)} terminée${doneCount(p)>1?'s':''}${p.endDate?' · jusqu’au '+fmt(p.endDate):''}</p><div class="progress"><span style="width:${progress(p)}%"></span></div></div><span class="project-arrow">›</span></a>`}
