 const todayStr=today(); let selectedDate=todayStr; let monthDate=new Date(); monthDate.setDate(1); let focusSeconds=1800, focusInterval=null, searchText='';
 const monthName=d=>d.toLocaleDateString('fr-FR',{month:'long',year:'numeric'});
