 const redrawTasks=()=>{$('#dashTaskList').innerHTML=taskMarkup();$('#dailyScheduleList').innerHTML=scheduleMarkup();$('#scheduleDateLabel').textContent=fmt(selectedDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#selectedDateLabel').textContent=fmt(selectedDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#dashCalendarGrid').innerHTML=calendarMarkup();$('#monthLabel').textContent=monthName(monthDate)};
